    stack_banner_badge: "LIVE DEMO",
    stack_banner_desc:
      "Test Edge-Ring, Center, Scratch, and Donut defect fingerprints, observe theoretical Poisson vs. Murphy yield calculations, and inspect STDF logs.",
    stack_banner_btn_yms: "Open YMS Wafer Map",
    stack_banner_btn_arch: "Full Architecture & 6 Pillars",
    faq_badge: "KNOWLEDGE BASE & ARCHITECTURE FAQ",
    faq_title: "Frequently Asked Questions",
    faq_sub:
      "Direct technical definitions, cleanroom standards, and architectural specifications of the SemiconFab.org platform.",
    faq_q1: "What is SemiconFab.org?",
    faq_a1:
      "SemiconFab.org is an open-access engineering digital twin platform for 300mm (12-inch) semiconductor wafer fabrication cleanrooms. It models architectural cleanroom elevations, subfab MEP utility networks, a 167 OEM equipment engineering taxonomy, real-time SECS/GEM & SEMI E10 industrial telemetry, and microscopic yield analytics directly in the browser.",
    faq_q2: "What cleanroom and architectural standards are modeled?",
    faq_a2:
      "The platform follows SEMI standards and ISO 14644-1 Class 1 cleanroom specifications (< 10 particles/m³ for particles ≥ 0.1 µm). It models a 4.5m process cleanroom with raised waffle-slab access flooring (600mm × 600mm perforated tiles), an amber-lit photolithography core, fan filter units (FFU), and a 6.0m subfab utility basement (Class 10,000 / ISO 7) for vacuum pumps, RF generators, and scrubbers.",
    faq_q3:
      "Which semiconductor equipment categories and OEM tools are included?",
    faq_a3:
      "The taxonomy covers 167 OEM equipment models across 13 process categories: Photolithography (EUV 13.5nm, ArFi 193nm Immersion, KrF), Photoresist Track (Coater/Developer), Dry Etching (RIE, ICP, ALE), Thin Films (PECVD, LPCVD, ALD, PVD, ECD), Wet Cleaning, CMP, Thermal Processing & Ion Implantation, and Metrology/Inspection (CD-SEM, DR-SEM, Ellipsometry).",
    faq_q4:
      "How does the Yield Management System (YMS) & Defect Simulator work?",
    faq_a4:
      "The YMS simulator implements Poisson (Y = exp(-D0 · A)) and Murphy yield models across an 8-stage cascading wafer flow. It includes interactive WebGL 300mm wafer maps that render WM-811K benchmark spatial defect fingerprints (Edge-Ring, Center, Scratch, Donut, Random) and STDF V4 datalog parsing.",
    faq_q5: "What industrial standards and telemetry protocols are supported?",
    faq_a5:
      "The platform supports SEMI E10 equipment reliability states (Productive, Standby, Scheduled Down, Unscheduled Down), SECS/GEM (SEMI E30/E37 HSMS) equipment communication variables (SVID/CEID), and standard semiconductor factory automation interfaces.",
    faq_q6:
      "Is SemiconFab.org free and open to universities and research institutions?",
    faq_a6:
      "Yes. SemiconFab.org is committed to open access for semiconductor engineering education, cleanroom workforce training, and digital twin research. It runs entirely inside standard web browsers without downloads or proprietary CAD software required.",

