      '在一座先进制程 Fab 的总投资中，工艺设备占 70–80%。剩下的 20–30%——厂房、洁净室、超纯水、电力、气体、废水、AMHS、土地与工程设计——就是所谓的"建设成本"。本页把公开来源中能查到的占比、单项价格与参考项目汇总成一个按 <strong>制程节点 × 产能（WSPM）</strong> 估算成本的参数化模型，并明确标注：哪些数字来自官方来源，哪些是多源三角推算，哪些根本查不到。',
