    faq_sub:
      "关于 SemiconFab.org 平台的权威技术定义、洁净室工业标准与架构规范指南。",
    faq_q1: "什么是 SemiconFab.org？",
    faq_a1:
      "SemiconFab.org 是一个面向 300mm（12英寸）半导体晶圆制造洁净室的全球开放工程级数字孪生平台。它在浏览器内直接建模洁净室物理建筑立体构造、Subfab 辅助动力管网系统、167 款半导体核心设备分类工程图鉴、实时 SECS/GEM 与 SEMI E10 工业遥测系统，以及前道微观级联良率仿真分析。",
    faq_q2: "平台遵循哪些洁净室与半导体工业标准？",
    faq_a2:
      "平台严格遵循 SEMI 国际标准以及 ISO 14644-1 Class 1（1级）洁净室规范（对于 ≥ 0.1 µm 的微粒，微粒浓度小于 10 颗/m³）。三维模型包含 4.5 米高前道工艺厂房（采用 600mm × 600mm 铝合金穿孔高架抗静电地板）、黄光微影曝光核心区、风机过滤机组（FFU）循环系统，以及 6.0 米高的下层动力 Subfab 地下室（Class 10,000 / ISO 7），用于安装干泵、射频电源与废气尾气洗涤塔。",
    faq_q3: "平台涵盖了哪些半导体设备分类与领军 OEM 机台？",
    faq_a3:
      "工程设备库覆盖 13 大半导体制造分类的 167 款核心 OEM 设备：光刻微影（13.5nm EUV、193nm 浸润式 ArFi、KrF）、涂胶显影机（Track）、等离子体干法刻蚀（RIE、ICP、ALE）、薄膜沉积（PECVD、LPCVD、ALD、PVD、超充铜电镀 ECD）、湿法清洗机、化学机械研磨（CMP）、高温退火氧化与离子注入机，以及量测检测机台（CD-SEM、缺陷复检 SEM、椭偏仪）。",
    faq_q4: "良率管理系统 (YMS) 与缺陷模拟器如何工作？",
    faq_a4:
      "YMS 模拟引擎在 8 大工序流中实现泊松模型 (Y = exp(-D0 · A)) 与墨菲良率模型。内嵌交互式 WebGL 300mm 晶圆图谱渲染，支持生成并分类 WM-811K 工业标准空间缺陷指纹（边缘环状、中心聚集、机械划痕、甜甜圈分布、随机分布），并提供 STDF V4 生产测试日志解析。",
    faq_q5: "平台支持哪些工业通信协议与自动化规范？",
    faq_a5:
      "平台支持 SEMI E10 设备可靠性状态机（运行、待料、计划停机、非计划故障停机）、SECS/GEM（SEMI E30 / E37 HSMS 高速消息服务）设备通信协议与参数采集（SVID/CEID），以及标准半导体工厂自动化调度接口。",
    faq_q6: "SemiconFab.org 是否向高校与科研机构免费开放？",
    faq_a6:
      "是的。SemiconFab.org 致力于半导体制造工程教育、洁净室产业人才培训以及数字孪生前沿学术研究的全球开放访问。所有功能均在标准现代网页浏览器中以 WebGL 原生运行，无需安装专有商业 CAD 软件或昂贵插件。",

