    stack_banner_title: "互動式 300mm 晶圓圖譜與空間缺陷分類器",
    stack_banner_badge: "實時演練",
    stack_banner_desc:
      "演練邊緣環狀、中心斑、刮痕與甜甜圈等典型缺陷指紋，實時計算泊松與墨菲理論良率，並解析標準 STDF 數據日誌。",
    stack_banner_btn_yms: "啟動 YMS 晶圓圖譜分析",
    stack_banner_btn_arch: "完整架構與六大技術支柱",
    faq_badge: "知識庫與架構技術規範 FAQ",
    faq_title: "常見工程與架構問題 (FAQ)",
    faq_sub:
      "關於 SemiconFab.org 平台的權威技術定義、無塵室工業標準與架構規範指南。",
    faq_q1: "什麼是 SemiconFab.org？",
    faq_a1:
      "SemiconFab.org 是一個面向 300mm（12吋）半導體晶圓製造無塵室的全球開放工程級數位雙生平台。它在瀏覽器內直接建模無塵室物理建築立體構造、Subfab 輔助動力管網系統、167 款半導體核心設備分類工程圖鑑、即時 SECS/GEM 與 SEMI E10 工業遙測系統，以及前道微觀級聯良率模擬分析。",
    faq_q2: "平台遵循哪些無塵室與半導體工業標準？",
    faq_a2:
      "平台嚴格遵循 SEMI 國際標準以及 ISO 14644-1 Class 1（1級）無塵室規範（對於 ≥ 0.1 µm 的微粒，微粒濃度小於 10 顆/m³）。三維模型包含 4.5 米高前道工藝廠房（採用 600mm × 600mm 鋁合金穿孔高架防靜電地板）、黃光微影曝光核心區、風機過濾機組（FFU）循環系統，以及 6.0 米高的下層動力 Subfab 地下室（Class 10,000 / ISO 7），用於安裝乾泵、射頻電源與廢氣尾氣洗滌塔。",
    faq_q3: "平台涵蓋了哪些半導體設備分類與領軍 OEM 機台？",
    faq_a3:
      "工程設備庫覆蓋 13 大半導體製造分類的 167 款核心 OEM 設備：微影曝光（13.5nm EUV、193nm 浸潤式 ArFi、KrF）、塗膠顯影機（Track）、電漿乾蝕刻（RIE、ICP、ALE）、薄膜沉積（PECVD、LPCVD、ALD、PVD、超充電鍍銅 ECD）、濕法清洗機、化學機械研磨（CMP）、高溫退火氧化與離子植入機，以及量測檢測機台（CD-SEM、缺陷複檢 SEM、橢偏儀）。",
    faq_q4: "良率管理系統 (YMS) 與缺陷模擬器如何運作？",
    faq_a4:
      "YMS 模擬引擎在 8 大工序流中實現泊松模型 (Y = exp(-D0 · A)) 與墨菲良率模型。內嵌互動式 WebGL 300mm 晶圓圖譜渲染，支援生成並分類 WM-811K 工業標準空間缺陷指紋（邊緣環狀、中心聚集、機械刮痕、甜甜圈分佈、隨機分佈），並提供 STDF V4 生產測試日誌解析。",
    faq_q5: "平台支援哪些工業通信協議與自動化規範？",
    faq_a5:
      "平台支援 SEMI E10 設備可靠性狀態機（運行、待料、計劃停機、非計劃故障停機）、SECS/GEM（SEMI E30 / E37 HSMS 高速消息服務）設備通信協議與參數採集（SVID/CEID），以及標準半導體工廠自動化調度接口。",
    faq_q6: "SemiconFab.org 是否向高校與科研機構免費開放？",
    faq_a6:
      "是的。SemiconFab.org 致力於半導體製造工程教育、無塵室產業人才培訓以及數位雙生前沿學術研究的全球開放訪問。所有功能均在標準現代網頁瀏覽器中以 WebGL 原生運行，無需安裝專有商業 CAD 軟體或昂貴外掛。",
