    stack_banner_desc:
      "エッジリング、センター、スクラッチ、ドーナツ等の欠陥パターンをテストし、ポアソン/マーフィー理論歩留まり計算とSTDFログを検証。",
    stack_banner_btn_yms: "YMSウェーハマップを開く",
    stack_banner_btn_arch: "全アーキテクチャと6大ピラー",
    faq_badge: "ナレッジベース & アーキテクチャ FAQ",
    faq_title: "よくある質問 (FAQ)",
    faq_sub:
      "SemiconFab.org プラットフォームの技術的定義、クリーンルーム規格、アーキテクチャ仕様。",
    faq_q1: "SemiconFab.org とは何ですか？",
    faq_a1:
      "SemiconFab.org は、300mm半導体ウェーハ製造クリーンルームのためのオープンなエンジニアリング・デジタルツインです。クリーンルーム建築立面、サブファブMEP配管設備、167 OEM 装置カタログ、SECS/GEM & SEMI E10産業テレメトリ、微細歩留まり解析をブラウザ上で再現します。",
    faq_q2: "どのようなクリーンルーム規格や建築基準が反映されていますか？",
    faq_a2:
      "SEMI規格およびISO 14644-1 クラス1規格（0.1µm以上の粒子が10個/m³未満）に準拠。600mm×600mmの有孔アクセスフロアを備えた高さ4.5mのプロセスクリーンルーム、黄色照明のリソグラフィコア、FFU循環系、真空ポンプや除害装置を収容する高さ6.0mのサブファブ（クラス10,000 / ISO 7）をモデル化しています。",
    faq_q3: "どの半導体製造装置カテゴリとOEM装置が含まれていますか？",
    faq_a3:
      "13主要カテゴリの167 OEM装置を網羅：フォトリソグラフィ（13.5nm EUV、193nm液浸ArFi、KrF）、コータ/デベロッパ（Track）、ドライエッチング（RIE、ICP、ALE）、薄膜成膜（PECVD、LPCVD、ALD、PVD、銅めっきECD）、ウェット洗浄、CMP研磨、熱処理・イオン注入、計測検査（CD-SEM、欠陥レビューSEM、エリプソメトリ）。",
    faq_q4:
      "歩留まり管理システム (YMS) & 欠陥シミュレータはどのように動作しますか？",
    faq_a4:
      "YMSシミュレータは8段階のカスケード工程フローにおいてポアソンモデル（Y = exp(-D0 · A)）とマーフィー歩留まりモデルを実装。WM-811Kベンチマーク空間欠陥パターン（エッジリング、センター、スクラッチ、ドーナツ、ランダム）を描画するWebGL 300mmウェーハマップとSTDF V4ログ解析を提供します。",
    faq_q5: "どの産業標準規格やテレメトリプロトコルに対応していますか？",
    faq_a5:
      "SEMI E10装置信頼性状態（稼働中、待機、計画停止、突発停止）、SECS/GEM（SEMI E30/E37 HSMS）装置通信変数（SVID/CEID）、標準的な半導体ファブ自動化インターフェースに対応しています。",
