    stack_banner_badge: "라이브 데모",
    stack_banner_desc:
      "에지 링, 센터, 스크래치, 도넛 등 대표 결함 지문을 테스트하고 포아송 및 머피 수율 계산과 STDF 로그를 확인하세요.",
    stack_banner_btn_yms: "YMS 웨이퍼 맵 열기",
    stack_banner_btn_arch: "전체 아키텍처 및 6대 기둥",
    faq_badge: "지식 베이스 & 아키텍처 FAQ",
    faq_title: "자주 묻는 질문 (FAQ)",
    faq_sub:
      "SemiconFab.org 플랫폼의 기술 정의, 클린룸 산업 표준 및 아키텍처 사양에 대한 안내입니다.",
    faq_q1: "SemiconFab.org는 무엇인가요?",
    faq_a1:
      "SemiconFab.org는 300mm(12인치) 반도체 웨이퍼 제조 클린룸을 위한 오픈 엔지니어링 디지털 트윈 플랫폼입니다. 건축 클린룸 입면, 서브팹 MEP 배관망, 167 OEM 장비 도감, 실시간 SECS/GEM 및 SEMI E10 원격 측정, 미세 수율 분석을 브라우저에서 직접 모델링합니다.",
    faq_q2: "어떤 클린룸 및 건축 표준이 모델링되었나요?",
    faq_a2:
      "플랫폼은 SEMI 표준 및 ISO 14644-1 클래스 1 사양(0.1µm 이상 입자 10개/m³ 미만)을 준수합니다. 600mm×600mm 타공 액세스 플로어가 적용된 4.5m 높이의 공정 클린룸, 황색광 노광 코어, FFU 순환 시스템, 진공 펌프와 스크러버를 위한 6.0m 서브팹 지하층(클래스 10,000 / ISO 7)을 모델링합니다.",
    faq_q3: "어떤 반도체 장비 범주 및 OEM 장비가 포함되어 있나요?",
    faq_a3:
      "13대 핵심 공정 167 OEM 장비 분류를 지원합니다: 포토리소그래피(13.5nm EUV, 193nm ArFi 이머전, KrF), 트랙 코터/디벨로퍼, 건식 식각(RIE, ICP, ALE), 박막 증착(PECVD, LPCVD, ALD, PVD, 구리 도금 ECD), 습식 세정, CMP, 열처리 및 이온 주입, 계측/검사(CD-SEM, 결함 리뷰 SEM, 엘립소미터).",
    faq_q4: "수율 관리 시스템(YMS) 및 결함 시뮬레이터는 어떻게 작동하나요?",
    faq_a4:
      "YMS 시뮬레이터는 8단계 캐스케이드 공정 흐름에서 포아송 모델(Y = exp(-D0 · A)) 및 머피 수율 모델을 구현합니다. WM-811K 벤치마크 공간 결함 지문(에지 링, 센터, 스크래치, 도넛, 랜덤)을 렌더링하는 대화형 WebGL 300mm 웨이퍼 맵과 STDF V4 로그 파싱을 포함합니다.",
    faq_q5: "어떤 산업 표준 및 원격 측정 프로토콜이 지원되나요?",
    faq_a5:
      "SEMI E10 장비 신뢰성 상태(생산 가동, 대기, 계획 정지, 불시 정지), SECS/GEM(SEMI E30/E37 HSMS) 장비 통신 변수(SVID/CEID) 및 표준 반도체 공장 자동화 인터페이스를 지원합니다.",
    faq_q6: "SemiconFab.org는 대학 및 연구 기관에 무료로 공개되나요?",
    faq_a6:
      "네. SemiconFab.org는 반도체 공학 교육, 클린룸 인력 교육 및 디지털 트윈 연구를 위해 무료 오픈 액세스를 제공합니다. 독점 CAD 소프트웨어 없이 표준 웹 브라우저의 WebGL에서 완벽하게 구동됩니다.",
