    stack_banner_badge: "LIVE-DEMO",
    stack_banner_desc:
      "Testen Sie Edge-Ring-, Center-, Scratch- und Donut-Defektmuster, beobachten Sie Poisson- vs. Murphy-Ausbeuteberechnungen und prüfen Sie STDF-Logs.",
    stack_banner_btn_yms: "YMS-Wafer-Map öffnen",
    stack_banner_btn_arch: "Gesamtarchitektur & 6 Säulen",
    faq_badge: "WISSENSDATENBANK & ARCHITEKTUR-FAQ",
    faq_title: "Häufig gestellte Fragen (FAQ)",
    faq_sub:
      "Direkte technische Definitionen, Reinraumstandards und Architekturspezifikationen der Plattform.",
    faq_q1: "Was ist SemiconFab.org?",
    faq_a1:
      "SemiconFab.org ist eine frei zugängliche Digital-Twin-Plattform für 300mm-Halbleiter-Reinräume. Sie modelliert Reinraum-Aufrisse, Subfab-MEP-Netzwerke, eine Taxonomie von 167 OEM-Anlagen, SECS/GEM- & SEMI E10-Telemetrie und mikroskopische Ausbeuteanalysen im Browser.",
    faq_q2: "Welche Reinraum- und Architekturstandards werden modelliert?",
    faq_a2:
      "Die Plattform erfüllt SEMI-Standards und ISO 14644-1 Klasse 1 (< 10 Partikel/m³ für ≥ 0,1 µm). Modelliert werden ein 4,5m Prozessreinraum mit Doppelboden (600×600mm Lochplatten), gelb beleuchteter Lithografie-Kern, FFUs und ein 6,0m Subfab-Geschoss (Klasse 10.000 / ISO 7) für Vakuumpumpen, HF-Generatoren und Wäscher.",
    faq_q3: "Welche Halbleiteranlagen-Kategorien und OEM-Tools sind enthalten?",
    faq_a3:
      "Die Taxonomie umfasst 167 OEM-Anlagen in 8 Hauptmodulen: Photolithografie (EUV 13,5nm, ArFi 193nm Immersion, KrF), Coater/Developer (Track), Trockenätzen (RIE, ICP, ALE), Dünnschichten (PECVD, LPCVD, ALD, PVD, ECD), Nassreinigung, CMP, thermische Prozesse & Ionenimplantation sowie Messtechnik/Inspektion (CD-SEM, DR-SEM, Ellipsometrie).",
    faq_q4:
      "Wie funktionieren das Ausbeutemanagementsystem (YMS) und der Defektsimulator?",
    faq_a4:
      "Der YMS-Simulator implementiert Poisson- (Y = exp(-D0 · A)) und Murphy-Ausbeutemodelle über einen 8-Stufen-Waferfluss. Er enthält interaktive WebGL-300mm-Wafer-Maps für WM-811K-Defektmuster (Edge-Ring, Center, Scratch, Donut, Random) und STDF V4 Datalog-Parsing.",
    faq_q5:
      "Welche Industriestandards und Telemetrieprotokolle werden unterstützt?",
    faq_a5:
      "Die Plattform unterstützt SEMI E10 Zuverlässigkeitszustände (Produktiv, Standby, Geplante Ausfallzeit, Ungeplante Ausfallzeit), SECS/GEM (SEMI E30/E37 HSMS) Variablen (SVID/CEID) und Standard-Automatisierungsschnittstellen.",
    faq_q6:
      "Ist SemiconFab.org für Universitäten und Forschungseinrichtungen kostenlos und offen?",
    faq_a6:
      "Ja. SemiconFab.org engagiert sich für freien Zugang in der Halbleiterausbildung, Reinraumschulung und Digital-Twin-Forschung. Es läuft vollständig in modernen Webbrowsern über WebGL ohne proprietäre CAD-Software.",
