    stack_banner_badge: "DÉMO EN DIRECT",
    stack_banner_desc:
      "Testez les signatures de défauts (anneau, centre, rayure, donut), comparez les modèles de Poisson et Murphy, et inspectez les journaux STDF.",
    stack_banner_btn_yms: "Ouvrir la carte de plaquette YMS",
    stack_banner_btn_arch: "Architecture complète & 6 piliers",
    faq_badge: "BASE DE CONNAISSANCES & FAQ TECHNIQUE",
    faq_title: "Foire aux questions (FAQ)",
    faq_sub:
      "Définitions techniques, normes de salle blanche et spécifications architecturales de la plateforme.",
    faq_q1: "Qu'est-ce que SemiconFab.org ?",
    faq_a1:
      "SemiconFab.org est une plateforme ouverte de jumeau numérique pour les salles blanches de fabrication de semi-conducteurs 300 mm. Elle modélise les élévations architecturales, les réseaux subfab, 167 équipements OEM, la télémétrie SECS/GEM & SEMI E10 et l'analyse de rendement dans le navigateur.",
    faq_q2:
      "Quelles normes de salle blanche et d'architecture sont modélisées ?",
    faq_a2:
      "La plateforme respecte les normes SEMI et ISO 14644-1 Classe 1 (< 10 particules/m³ pour ≥ 0,1 µm). Elle modélise une salle blanche de 4,5 m avec faux-plancher perforé (dalles 600×600 mm), un cœur de lithographie à lumière jaune, des FFU et un sous-sol technique de 6,0 m (Classe 10 000 / ISO 7) pour pompes et laveurs.",
    faq_q3: "Quelles catégories d'équipements et machines OEM sont incluses ?",
    faq_a3:
      "La taxonomie couvre 167 équipements OEM sur 8 modules majeurs : photolithographie (EUV 13,5 nm, ArFi 193 nm immersion, KrF), pisteuse (track), gravure sèche (RIE, ICP, ALE), couches minces (PECVD, LPCVD, ALD, PVD, ECD), nettoyage humide, CMP, traitement thermique & implantation ionique, et métrologie/inspection (CD-SEM, DR-SEM, ellipsométrie).",
    faq_q4:
      "Comment fonctionnent le système de gestion du rendement (YMS) et le simulateur de défauts ?",
    faq_a4:
      "Le simulateur YMS implémente les modèles de Poisson (Y = exp(-D0 · A)) et de Murphy sur un flux en 8 étapes. Il intègre des cartes WebGL 300 mm affichant les motifs de défauts WM-811K (anneau de bord, centre, rayure, donut, aléatoire) et l'analyse de journaux STDF V4.",
    faq_q5:
      "Quelles normes industrielles et protocoles de télémétrie sont pris en charge ?",
    faq_a5:
      "La plateforme prend en charge les états de fiabilité SEMI E10 (Productif, Veille, Arrêt planifié, Arrêt imprévu), les variables de communication SECS/GEM (SEMI E30/E37 HSMS, SVID/CEID) et les interfaces d'automatisation de fonderie.",
    faq_q6:
      "SemiconFab.org est-il gratuit et accessible aux universités et centres de recherche ?",
    faq_a6:
      "Oui. SemiconFab.org s'engage en faveur du libre accès pour la formation en ingénierie des semi-conducteurs et la recherche. Il s'exécute nativement dans les navigateurs modernes via WebGL sans logiciel propriétaire.",
