    stack_banner_badge: "DEMO LIVE",
    stack_banner_desc:
      "Testa impronte di difetti ad anello, centro, graffio e ciambella, confronta i calcoli di resa di Poisson e Murphy e ispeziona i log STDF.",
    stack_banner_btn_yms: "Apri mappa wafer YMS",
    stack_banner_btn_arch: "Architettura completa e 6 pilastri",
    faq_badge: "BASE DI CONOSCENZA & FAQ DI ARCHITETTURA",
    faq_title: "Domande frequenti (FAQ)",
    faq_sub:
      "Definizioni tecniche, standard di camera bianca e specifiche architetturali della piattaforma.",
    faq_q1: "Che cos'è SemiconFab.org?",
    faq_a1:
      "SemiconFab.org è una piattaforma aperta di gemello digitale per camere bianche di fabbricazione wafer da 300 mm. Modella prospetti architettonici, reti subfab MEP, tassonomia di 167 macchinari OEM, telemetria SECS/GEM e SEMI E10 e analisi microscopica della resa nel browser.",
    faq_q2: "Quali standard di camera bianca e architettura sono modellati?",
    faq_a2:
      "La piattaforma rispetta gli standard SEMI e ISO 14644-1 Classe 1 (< 10 particelle/m³ per ≥ 0,1 µm). Modella una camera bianca di processo da 4,5 m con pavimento sopraelevato forato (piastrelle 600×600 mm), nucleo fotolitografico a luce ambrata, FFU e un piano subfab da 6,0 m (Classe 10.000 / ISO 7) per pompe a vuoto e scrubber.",
    faq_q3: "Quali categorie di apparecchiature e macchinari OEM sono inclusi?",
    faq_a3:
      "La tassonomia include 167 apparecchiature OEM in 13 categorie: fotolitografia (EUV 13,5 nm, ArFi 193 nm immersione, KrF), coater/developer (track), incisione a secco (RIE, ICP, ALE), film sottili (PECVD, LPCVD, ALD, PVD, ECD), pulizia a umido, CMP, trattamenti termici e impiantazione ionica, metrologia e ispezione (CD-SEM, DR-SEM, ellissometria).",
    faq_q4:
      "Come funzionano il sistema di gestione della resa (YMS) e il simulatore di difetti?",
    faq_a4:
      "Il simulatore YMS implementa i modelli di resa di Poisson (Y = exp(-D0 · A)) e Murphy su un flusso wafer a 8 stadi. Include mappe wafer WebGL da 300 mm con impronte di difetti spaziali WM-811K (anello di bordo, centro, graffio, ciambella, casuale) e parsing log STDF V4.",
    faq_q5:
      "Quali standard industriali e protocolli di telemetria sono supportati?",
    faq_a5:
      "La piattaforma supporta gli stati di affidabilità SEMI E10 (Produttivo, Standby, Fermo programmato, Guasto non programmato), variabili di comunicazione SECS/GEM (SEMI E30/E37 HSMS, SVID/CEID) e interfacce di automazione.",
    faq_q6:
      "SemiconFab.org è gratuito e aperto a università e istituti di ricerca?",
    faq_a6:
      "Sì. SemiconFab.org promuove l'accesso aperto per la formazione ingegneristica, l'addestramento in camera bianca e la ricerca sui gemelli digitali. Funziona nativamente nei browser moderni con WebGL senza software CAD proprietario.",
