    stack_banner_btn_yms: "Abrir mapa de obleas YMS",
    stack_banner_btn_arch: "Arquitectura completa y 6 pilares",
    faq_badge: "BASE DE CONOCIMIENTO Y PREGUNTAS FRECUENTES",
    faq_title: "Preguntas frecuentes (FAQ)",
    faq_sub:
      "Definiciones técnicas directas, estándares de sala limpia y especificaciones de arquitectura.",
    faq_q1: "¿Qué es SemiconFab.org?",
    faq_a1:
      "SemiconFab.org es una plataforma abierta de gemelo digital para salas limpias de fabricación de obleas de 300 mm. Modela elevaciones arquitectónicas, redes MEP de subfab, taxonomía de 167 equipos OEM, telemetría SECS/GEM y SEMI E10 y análisis de rendimiento directamente en el navegador.",
    faq_q2: "¿Qué estándares de sala limpia y arquitectura están modelados?",
    faq_a2:
      "La plataforma sigue normas SEMI e ISO 14644-1 Clase 1 (< 10 partículas/m³ para ≥ 0,1 µm). Modela una sala de procesos de 4,5 m con suelo técnico perforado (losas 600×600 mm), núcleo de fotolitografía con luz ámbar, FFU y un sótano subfab de 6,0 m (Clase 10.000 / ISO 7) para bombas de vacío y lavadores.",
    faq_q3: "¿Qué categorías de equipos y máquinas OEM están incluidas?",
    faq_a3:
      "La taxonomía abarca 167 equipos OEM en 13 categorías principales: fotolitografía (EUV 13,5 nm, ArFi 193 nm inmersión, KrF), pista coater/developer (track), grabado en seco (RIE, ICP, ALE), películas delgadas (PECVD, LPCVD, ALD, PVD, ECD), limpieza húmeda, CMP, procesos térmicos e implantación iónica, y metrología/inspección (CD-SEM, DR-SEM, elipsometría).",
    faq_q4:
      "¿Cómo funcionan el sistema de gestión de rendimiento (YMS) y el simulador de defectos?",
    faq_a4:
      "El simulador YMS implementa modelos de rendimiento de Poisson (Y = exp(-D0 · A)) y Murphy en un flujo de 8 etapas. Incluye mapas de obleas WebGL de 300 mm que renderizan patrones WM-811K (anillo de borde, centro, rayón, donut, aleatorio) y análisis de registros STDF V4.",
    faq_q5:
      "¿Qué estándares industriales y protocolos de telemetría son compatibles?",
    faq_a5:
      "La plataforma admite estados de confiabilidad SEMI E10 (Productivo, En espera, Parada programada, Parada no programada), variables de comunicación SECS/GEM (SEMI E30/E37 HSMS, SVID/CEID) e interfaces estándar de automatización.",
    faq_q6:
      "¿SemiconFab.org es gratuito y abierto para universidades e institutos de investigación?",
    faq_a6:
      "Sí. SemiconFab.org está comprometido con el acceso abierto para la educación en ingeniería de semiconductores, capacitación en salas limpias e investigación. Se ejecuta de forma nativa en navegadores web con WebGL sin software CAD propietario.",
